    cmp = az.compare({k: v for k, v in idata_train.items() if k in sel_mod})
    if return_df:
        return(cmp)
    fig, ax = plt.subplots(figsize=(4, cmp.shape[0] * 0.5))
    g = az.plot_compare(cmp, ax=ax, textsize=10)
    ax.legend()
    return((fig, ax))

